import {
  IsInt,
  IsNotEmpty,
  IsString,
  IsUUID,
  Max,
  MaxLength,
  Min,
} from 'class-validator';
import { ApiProperty } from '@nestjs/swagger';

export class SegmentPingDto {
  @ApiProperty({
    description: 'UUIDv4 identifier of the video being watched',
    example: '3fa85f64-5717-4562-b3fc-2c963f66afa6',
    format: 'uuid',
  })
  @IsUUID('4', { message: 'videoId must be a valid UUIDv4' })
  @IsNotEmpty()
  videoId: string;

  @ApiProperty({
    description:
      'Pseudonymous playback session identifier generated by player client (max 128 chars)',
    example: 'sess_9f83a2bc4e61',
  })
  @IsString()
  @IsNotEmpty()
  @MaxLength(128)
  sessionId: string;

  @ApiProperty({
    description:
      'Increment of active watch time in seconds during this heartbeat interval (bounded between 1 and 60 seconds)',
    example: 10,
    minimum: 1,
    maximum: 60,
  })
  @IsInt()
  @Min(1)
  @Max(60) // Enforce server-side bounds to prevent duration inflation
  watchDurationSeconds: number;

  @ApiProperty({
    description:
      'Count of HLS .ts chunks or video fragments downloaded by player in this segment interval',
    example: 2,
    minimum: 1,
    maximum: 20,
  })
  @IsInt()
  @Min(1)
  @Max(20)
  segmentsRequested: number;
}
